// @ts-expect-error Svelte client entry under SSR resolution.
import{mount,tick,unmount}from'../../../../node_modules/svelte/src/index-client.js'
import{afterEach,beforeEach,expect,it,vi}from'vitest'
import{evaluateNestedFrame,type NativeNestedProject}from'$lib/api'
import{nestedComposition,nestedHistory,closeNestedComposition,undoNestedComposition}from'$lib/state/nestedComposition.svelte'
import Inspector from'./NestedConcatSpatialInspector.svelte'
vi.mock('$lib/api',()=>({evaluateNestedFrame:vi.fn()}))
let component:ReturnType<typeof mount>|undefined
beforeEach(()=>{closeNestedComposition();vi.mocked(evaluateNestedFrame).mockResolvedValue({entries:[]});nestedComposition.document={schemaVersion:1,root:'root',compositions:{root:{content:{tracks:[{kind:'video',id:'track',name:'Video',locked:false,clips:[{id:'clip',effects:[]}]}]},instances:[]}}}as unknown as NativeNestedProject;nestedComposition.renderedOutputs={root:'movie'}})
afterEach(async()=>{if(component)await unmount(component);component=undefined;closeNestedComposition();document.body.innerHTML='';vi.clearAllMocks()})
function click(text:string){const button=[...document.querySelectorAll('button')].find(b=>b.textContent?.trim()===text);expect(button).toBeDefined();button!.click()}
it('adds distinct source packages, changes independent controls and restores the document with Undo',async()=>{const before=JSON.stringify(nestedComposition.document);component=mount(Inspector,{target:document.body,props:{token:'first'}});await tick();click('Добавить Concat Sharpen');await vi.waitFor(()=>expect(nestedHistory.past).toHaveLength(1));await tick();const amount=document.querySelector<HTMLInputElement>('input[aria-label="clip Concat Sharpen amount"]')!;expect([amount.value,amount.min,amount.max,amount.step]).toEqual(['1','0.2','3','0.05']);amount.value='2';amount.dispatchEvent(new Event('change',{bubbles:true}));await vi.waitFor(()=>expect(nestedHistory.past).toHaveLength(2));await tick();click('Добавить Concat Vignette');await vi.waitFor(()=>expect(nestedHistory.past).toHaveLength(3));await tick();const strength=document.querySelector<HTMLInputElement>('input[aria-label="clip Concat Vignette strength"]')!;expect([strength.value,strength.min,strength.max]).toEqual(['50','10','100']);strength.value='80';strength.dispatchEvent(new Event('change',{bubbles:true}));await vi.waitFor(()=>expect(nestedHistory.past).toHaveLength(4));const track=nestedComposition.document!.compositions.root!.content.tracks[0]!;if(track.kind!=='video')throw new Error('video');expect(track.clips[0]!.effects).toEqual([{kind:'concat_sharpen',parameters:{amount:2}},{kind:'concat_vignette',parameters:{strength:80}}]);await tick();click('Сбросить Concat Sharpen');await vi.waitFor(()=>expect(nestedHistory.past).toHaveLength(5));await tick();click('Удалить Concat Vignette');await vi.waitFor(()=>expect(nestedHistory.past).toHaveLength(6));for(let i=0;i<6;i++)undoNestedComposition();expect(JSON.stringify(nestedComposition.document)).toBe(before);expect(nestedComposition.renderedOutputs).toEqual({root:'movie'})})
it('disables authoring while the editor is disabled',async()=>{component=mount(Inspector,{target:document.body,props:{disabled:true}});await tick();expect([...document.querySelectorAll('button')].every(b=>b.disabled)).toBe(true)})
it('authors source Contrast Pop independently and undoes one parameter edit',async()=>{component=mount(Inspector,{target:document.body,props:{token:'first'}});await tick();click('Добавить Concat Contrast Pop');await vi.waitFor(()=>expect(nestedHistory.past).toHaveLength(1));await tick();const input=document.querySelector<HTMLInputElement>('input[aria-label="clip Concat Contrast Pop contrast"]')!;expect([input.value,input.min,input.max,input.step]).toEqual(['1.25','1','2','0.05']);input.value='1.8';input.dispatchEvent(new Event('change',{bubbles:true}));await vi.waitFor(()=>expect(nestedHistory.past).toHaveLength(2));const track=nestedComposition.document!.compositions.root!.content.tracks[0]!;if(track.kind!=='video')throw new Error('video');expect(track.clips[0]!.effects).toEqual([{kind:'concat_contrast_pop',parameters:{contrast:1.8}}]);undoNestedComposition();const restored=nestedComposition.document!.compositions.root!.content.tracks[0]!;if(restored.kind!=='video')throw new Error('video');expect(restored.clips[0]!.effects).toEqual([{kind:'concat_contrast_pop',parameters:{}}])})

