for(const [name,kind,base,min,max,next]of [['Cool','concat_cool',8500,7000,11000,9500],['Warm','concat_warm',4600,3000,6000,4750]]as const){
 it(`authors ${name} temperature in Kelvin and restores its default`,async()=>{
  component=mount(Inspector,{target:document.body,props:{token:'first'}});await tick();click(`Добавить Concat ${name}`);await vi.waitFor(()=>expect(nestedHistory.past).toHaveLength(1));await tick();
  const input=document.querySelector<HTMLInputElement>(`input[aria-label="clip Concat ${name} temperature"]`)!;
  expect([input.value,input.min,input.max,input.step]).toEqual([String(base),String(min),String(max),'50']);
  input.value=String(next);input.dispatchEvent(new Event('change',{bubbles:true}));await vi.waitFor(()=>expect(nestedHistory.past).toHaveLength(2));
  const track=nestedComposition.document!.compositions.root!.content.tracks[0]!;if(track.kind!=='video')throw new Error('video');expect(track.clips[0]!.effects).toEqual([{kind,parameters:{temperature:next}}]);
  undoNestedComposition();await tick();expect(document.querySelector<HTMLInputElement>(`input[aria-label="clip Concat ${name} temperature"]`)!.value).toBe(String(base));
 })
}
